import sys

MOD = 998244353

def main() -> None:
    data = sys.stdin.buffer.read().split()
    n = int(data[0])
    watches = [(int(data[1 + 2 * i]), int(data[2 + 2 * i])) for i in range(n)]
    watches.sort()
    ends = sorted({e for _, e in watches})
    m = len(ends)
    # Rank 1 is the largest ending hour, so "ends strictly after mine" is a prefix of the tree.
    rank = {v: m - i for i, v in enumerate(ends)}
    best = [0] * (m + 1)
    count = [0] * (m + 1)

    def insert(i, b, c):
        while i <= m:
            if best[i] < b:
                best[i] = b
                count[i] = c
            elif best[i] == b:
                count[i] = (count[i] + c) % MOD
            i += i & -i

    def prefix(i):
        b = 0
        c = 0
        while i > 0:
            if best[i] > b:
                b = best[i]
                c = count[i]
            elif best[i] == b and b > 0:
                c = (c + count[i]) % MOD
            i -= i & -i
        return b, c

    top = 0
    tops = 0
    i = 0
    while i < n:
        j = i
        while j < n and watches[j][0] == watches[i][0]:
            j += 1
        # Watches that begin at the same hour can never sit one inside the other, so the whole
        # group is answered from the state before any of it is filed.
        pending = []
        for k in range(i, j):
            r = rank[watches[k][1]]
            b, c = prefix(r - 1)
            if b == 0:
                deep, ways = 1, 1
            else:
                deep, ways = b + 1, c
            pending.append((r, deep, ways))
            if deep > top:
                top = deep
                tops = ways
            elif deep == top:
                tops = (tops + ways) % MOD
        for r, deep, ways in pending:
            insert(r, deep, ways)
        i = j
    sys.stdout.write(str(top) + " " + str(tops % MOD) + "\n")

main()
